(async () => {
  const samples = [];
  const originLat = 12.9716;
  const originLon = 77.5946;
  const t0 = 1700000000000;
  for (let index = 0; index < 31; index += 1) {
    const t = index * 3000;
    let x;
    let y;
    if (t <= 42000) {
      x = 1.5 * t / 1000;
      y = 0;
    } else {
      const elapsed = (t - 42000) / 1000;
      const rad = 70 * Math.PI / 180;
      x = 1.5 * 42 + 1.5 * elapsed * Math.cos(rad);
      y = 1.5 * elapsed * Math.sin(rad);
    }
    const lat = originLat + (y / 6371000) * (180 / Math.PI);
    const lon = originLon + (x / (6371000 * Math.cos(originLat * Math.PI / 180))) * (180 / Math.PI);
    samples.push({ latitude: lat, longitude: lon, accuracy_m: 5, timestamp_ms: t0 + t });
  }
  const key = "ab".repeat(32);
  const response = await fetch("/api/v1/soundprints", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-idempotency-key": "browser-corner-1",
      "x-job-key": key,
    },
    body: JSON.stringify({ schema_version: "1", mood: "warm_cinematic", consent_version: "1", samples }),
  });
  const payload = await response.json();
  sessionStorage.setItem("footwork-live-job", JSON.stringify({ jobId: payload.job_id, jobKey: key }));
  sessionStorage.setItem("footwork-generation", "live");
  return { status: response.status, mode: payload.mode, stage: payload.stage, jobId: payload.job_id };
})()
